Shell.example:
Shell {
    Monitor { Name: Main, Index: default, Children { } }
}

Monitor.example:
Monitor {
    Name: Main
    Index: default
    Children {
        Bar { Name: Top_Bar, Edge: TOP, Width: EXPAND, Height: 32 }
    }
}

Bar.example:
Bar {
    Name: Top_Bar
    Edge: TOP
    Width: EXPAND
    Height: 32
    Style { Background: $color.surface }
    Children { Text { Text: "Hello" } }
}

Panel.example:
Panel {
    Name: Launcher
    Anchor: [TOP, LEFT]
    Inset: [8, 40, 0, 0]
    Width: 320
    Height: 400
    Visible: false
    Children { Text { Text: "Apps" } }
}

Popup.example:
Popup {
    Name: Tray_Menu
    Attach: BOTTOM
    Alignment: START
    Children { Text { Text: "Menu" } }
}

Frame.example:
Frame {
    Name: Screen_Frame
    Thickness: 8
    Corner_Radius: 12
    Style { Background: $color.surface }
}

FlexBox.example:
FlexBox {
    Flex: HORIZONTAL
    Spacing: 8
    Align_Items: CENTER
    Children { Text { Text: "One" }, Text { Text: "Two" } }
}
